int _pass = 0;
int _fail = 0;
void _test(int num, int got, int expected) {
    bool passed = got == expected;
    std::cout << "---------------------\n";
    std::cout << "Test " << num << ":\n";
    std::cout << (passed ? "Pass" : "Fail") << "\n";
    if (passed) _pass++; else _fail++;
}

int main() {
    const FSizeArr<int, 3> tester1 = {1, 2, 3};
    _test(1, 1, tester1.get_data() ? 1 : 0);
    _test(2, 3, tester1.back());
    _test(3, 1, tester1.front());
    std::cout << "---------------------\n";
    std::cout << _pass << " passed, " << _fail << " failed\n";
    return 0;
}
